// Phase 131 Plan 01 Task 2 (ROUTE-01 / Pattern 4). Codegen script: reads
// routing_destinations.destination_key from the live registry for ALL swarms and
// writes a generated TS per-swarm map + literal-union to
// web/lib/swarms/routing-destinations.generated.ts.
//
// Why: the destination bucket set is registry-data (source of truth). This keeps
// strict TS compile-time safety AND zero-edit onboarding — after a new bucket
// row is INSERTed into routing_destinations, run `npm run codegen` and commit
// the regenerated file. The Orq agent's bucket enum is built from the SAME
// registry read so TS ↔ DB ↔ Orq stay single-source. Operator never edits the
// .generated.ts by hand.
//
// Mirrors web/scripts/gen-intent-types.ts verbatim (per-swarm map, alphabetical
// sort for stable diff, skip-if-identical idempotency, require.main guard).
//
// Run:   npx tsx scripts/gen-routing-destinations.ts
// CI:    npm run codegen   (then `git diff --exit-code` to detect drift)

import { createClient } from "@supabase/supabase-js";
import {
  writeFileSync,
  mkdirSync,
  readFileSync,
  existsSync,
} from "node:fs";
import { dirname, resolve } from "node:path";
import { config as loadDotenv } from "dotenv";

loadDotenv({ path: resolve(__dirname, "..", ".env.local") });

const OUTPUT_PATH = resolve(
  __dirname,
  "..",
  "lib",
  "swarms",
  "routing-destinations.generated.ts",
);

const HEADER = `// AUTO-GENERATED by scripts/gen-routing-destinations.ts (Phase 131 / ROUTE-01).
// DO NOT EDIT BY HAND. Run \`npm run codegen\` after registry changes.
//
// Source of truth: public.routing_destinations.destination_key (Phase 131
// registry), grouped by swarm_type, active rows only. Regenerate when a new
// destination bucket is INSERTed into the registry.

`;

interface RoutingDestKeyRow {
  swarm_type: string;
  destination_key: string;
}

function renderBody(rows: RoutingDestKeyRow[]): string {
  if (rows.length === 0) {
    // Defensive: an empty registry shouldn't happen in practice, but emit a
    // valid TS file anyway so the build doesn't break in dev.
    return (
      `export const DESTINATION_KEYS_BY_SWARM = {} as const;\n\n` +
      `export type DestinationKey = never;\n`
    );
  }
  // Group destination_keys by swarm_type.
  const bySwarm = new Map<string, Set<string>>();
  for (const r of rows) {
    if (!bySwarm.has(r.swarm_type)) bySwarm.set(r.swarm_type, new Set());
    bySwarm.get(r.swarm_type)!.add(r.destination_key);
  }
  // Stable diff: sort swarm_type keys and the inner destination_key arrays
  // alphabetically.
  const sortedSwarms = [...bySwarm.keys()].sort((a, b) => a.localeCompare(b));
  const entries = sortedSwarms
    .map((swarmType) => {
      const keys = [...bySwarm.get(swarmType)!].sort();
      const list = keys.map((k) => `"${k}"`).join(", ");
      return `  ${JSON.stringify(swarmType)}: [${list}],`;
    })
    .join("\n");
  return (
    `export const DESTINATION_KEYS_BY_SWARM = {\n${entries}\n} as const;\n\n` +
    `export type DestinationKey =\n  (typeof DESTINATION_KEYS_BY_SWARM)[keyof typeof DESTINATION_KEYS_BY_SWARM][number];\n`
  );
}

export async function main(): Promise<void> {
  const url =
    process.env.SUPABASE_URL ?? process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key =
    process.env.SUPABASE_SERVICE_ROLE_KEY ?? process.env.SUPABASE_SERVICE_KEY;
  if (!url || !key) {
    throw new Error(
      "[gen-routing-destinations] SUPABASE_URL (or NEXT_PUBLIC_SUPABASE_URL) + SUPABASE_SERVICE_ROLE_KEY required",
    );
  }
  const admin = createClient(url, key, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  const { data, error } = await admin
    .from("routing_destinations")
    .select("swarm_type, destination_key")
    .eq("active", true)
    .order("swarm_type")
    .order("destination_key");
  if (error) {
    // Pre-apply tolerance (Phase 131 Plan 01): the routing_destinations table is
    // created by 20260617_phase131_routing_destinations.sql, which the operator
    // applies at the Task 3 checkpoint. Until then the live registry has no
    // table — PostgREST returns "Could not find the table … in the schema
    // cache" (PGRST205). Skip the rewrite (leave the committed generated file
    // untouched) instead of hard-failing the whole codegen chain. Any OTHER
    // error still throws. The Task 3 checkpoint re-runs codegen after apply and
    // asserts `git diff --exit-code` is clean against this committed file.
    const missingTable =
      /could not find the table/i.test(error.message) ||
      (error as { code?: string }).code === "PGRST205";
    if (missingTable) {
      console.warn(
        "[gen-routing-destinations] routing_destinations table not found yet " +
          "(pre-apply) — leaving the committed generated file untouched. " +
          "Re-run after the Phase 131 migration applies.",
      );
      return;
    }
    throw new Error(
      `[gen-routing-destinations] routing_destinations query failed: ${error.message}`,
    );
  }
  const rows: RoutingDestKeyRow[] = (data ?? []).map(
    (r: { swarm_type: string; destination_key: string }) => ({
      swarm_type: r.swarm_type,
      destination_key: r.destination_key,
    }),
  );

  const next = HEADER + renderBody(rows);

  mkdirSync(dirname(OUTPUT_PATH), { recursive: true });
  const existing = existsSync(OUTPUT_PATH)
    ? readFileSync(OUTPUT_PATH, "utf8")
    : null;

  if (existing === next) {
    console.log(
      `[gen-routing-destinations] already up-to-date (${rows.length} destination rows) — no write`,
    );
    return;
  }

  writeFileSync(OUTPUT_PATH, next, "utf8");
  console.log(
    `[gen-routing-destinations] wrote ${rows.length} destination rows to ${OUTPUT_PATH}`,
  );
}

// Auto-run when executed via `tsx scripts/gen-routing-destinations.ts`. The
// `require.main === module` guard prevents accidental execution on import.
if (require.main === module) {
  main().catch((err) => {
    console.error("[gen-routing-destinations] FAILED:", err);
    process.exit(1);
  });
}
